const { DatabaseSync } = require('node:sqlite');
const crypto = require('crypto');
const fs = require('fs');

const input = $input.first().json;
const message = (input.message || '').trim();

// Support both formats: "command, param1, param2" and "command param1, param2"
const commaParts = message.split(',').map(p => p.trim());
const firstWord = commaParts[0].split(' ')[0].toLowerCase();
const restOfFirst = commaParts[0].split(' ').slice(1).join(' ');

const action = firstWord;
const username = commaParts[1] || restOfFirst || '';
const password = commaParts[2] || '';
const email = commaParts[3] || '';

const result = {
  chatInput: message,
  userId: input.userId || '',
  sessionId: input.sessionId || '',
  authResult: null,
  authMessage: '',
  authData: null
};

if (!['login', 'register'].includes(action) || !username) {
  return [{ json: result }];
}

try {
  const db = new DatabaseSync('/home/node/.n8n/auth.db');
  const user = db.prepare('SELECT * FROM users WHERE LOWER(username) = LOWER(?)').get(username);

  if (action === 'login') {
    if (!user) {
      result.authResult = 'user_not_found';
      result.authMessage = "L'utilisateur " + username + " n'existe pas.";
    } else if (!user.active) {
      result.authResult = 'account_disabled';
      result.authMessage = 'Compte désactivé.';
    } else {
      const pwHash = crypto.createHash('sha256').update((password || '').trim()).digest('hex');
      if (user.password === pwHash) {
        result.authResult = 'login_ok';
        result.authMessage = 'Connexion réussie !';
        result.authData = { id: user.id, username: user.username, email: user.email };
      } else {
        result.authResult = 'wrong_password';
        result.authMessage = 'Mot de passe incorrect.';
      }
    }
  }

  if (action === 'register') {
    if (user) {
      result.authResult = 'user_exists';
      result.authMessage = "Nom d'utilisateur déjà pris.";
    } else if (!email || !password || password.length < 6) {
      result.authResult = 'missing_fields';
      result.authMessage = 'Email et mot de passe (6+ car.) requis.';
    } else {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const pwHash = crypto.createHash('sha256').update(password.trim()).digest('hex');
      db.prepare("INSERT INTO users (id, username, email, password, token, createdAt, gdpr_consent, active) VALUES (?, ?, ?, ?, ?, ?, 1, 1)").run(id, username, email, pwHash, null, now);

      try {
        const usersFile = '/home/node/.n8n/users.json';
        let usersData = { users: [] };
        if (fs.existsSync(usersFile)) usersData = JSON.parse(fs.readFileSync(usersFile, 'utf8'));
        usersData.users.push({ id, username, email, password: pwHash, createdAt: now, gdpr_consent: 1, active: true });
        fs.writeFileSync(usersFile, JSON.stringify(usersData, null, 2));
      } catch(e) {}

      result.authResult = 'register_ok';
      result.authMessage = 'Compte créé avec succès !';
      result.authData = { id, username, email };
    }
  }
} catch(e) {
  result.authResult = 'error';
  result.authMessage = 'Erreur technique: ' + e.message;
}

return [{ json: result }];

