const { DatabaseSync } = require('node:sqlite');
const fs = require('fs');

const input = $input.first().json;
const userId = input.authData?.id || input.userId || '';

if (userId) {
  try {
    const db = new DatabaseSync('/home/node/.n8n/auth.db');
    db.prepare('UPDATE users SET active = 0 WHERE id = ?').run(userId);
  } catch(e) {}
  try {
    const prefsFile = '/home/node/.n8n/preferences.json';
    if (fs.existsSync(prefsFile)) {
      let data = JSON.parse(fs.readFileSync(prefsFile, 'utf8'));
      const pref = data.preferences?.find(p => p.userId === userId);
      if (pref) pref.active = false;
      fs.writeFileSync(prefsFile, JSON.stringify(data, null, 2));
    }
  } catch(e) {}
}

