const input = $input.first().json;
const response = input.output || input.message?.content || '';
return [{ json: { response } }];

const item = $input.first().json;
const message = item.message || '';
const cats = ['technologie','ia','intelligence artificielle','science','sante','santé','business','sport','divertissement','politique','environnement'];
const lower = message.toLowerCase();
const sessionId = item.sessionId || '';
const interests = cats.filter(c => lower.includes(c));
if (interests.length > 0 && sessionId) {
  try {
    const fs = require('fs');
    const pFile = '/home/node/.n8n/preferences.json';
    let prefs = { preferences: [] };
    if (fs.existsSync(pFile)) prefs = JSON.parse(fs.readFileSync(pFile, 'utf8'));
    prefs.preferences.push({ userId: sessionId, interests, updatedAt: new Date().toISOString() });
    fs.writeFileSync(pFile, JSON.stringify(prefs, null, 2));
  } catch(e) {}
}
return [{json: {...item, chatInput: message}}];
